// Cyrus API v1 crypto, shared by both directions. SERVER ONLY (node:crypto). HOST SEAM: no Nxeon imports.
//   service tokens      cyk_<keyId>_<secret>; Cyrus stores sha256(secret) only
//   subject assertions  b64url(JSON claims).b64url(Ed25519 sig): the caller (Nxeon) signs WHO the request is for;
//                       Cyrus holds only the public key. sub = stable subject id, never an email. Single use (jti).
//   request signing     HMAC-SHA256 over method/path/timestamp/nonce/body hash (direction A: Cyrus -> Nxeon partner API)
//   webhooks            v1=<hex HMAC-SHA256(secret, id.timestamp.body)> with a dedicated secret + replay window
import { createHash, createHmac, randomBytes, sign as edSign, timingSafeEqual, verify as edVerify, type KeyObject } from "node:crypto";

export const sha256Hex = (s: string | Buffer) => createHash("sha256").update(s).digest("hex");
const b64u = (b: Buffer | string) => Buffer.from(b).toString("base64url");

/** Constant-time string compare (false on any length difference). */
export function safeEqual(a: string, b: string): boolean {
  const x = Buffer.from(a), y = Buffer.from(b);
  return x.length === y.length && timingSafeEqual(x, y);
}

// ------------------------------------------------------------------------------------------------ service tokens
export const TOKEN_RE = /^cyk_([a-z0-9]{4,32})_([A-Za-z0-9_-]{32,128})$/;
export function parseServiceToken(raw: string | null | undefined): { keyId: string; secret: string } | null {
  const m = TOKEN_RE.exec(String(raw ?? "").trim());
  return m ? { keyId: m[1], secret: m[2] } : null;
}
/** For owner tooling and tests: a fresh token and the hash to put in CYRUS_API_V1_KEYS. */
export function mintServiceToken(keyId: string): { token: string; sha256: string } {
  if (!/^[a-z0-9]{4,32}$/.test(keyId)) throw new Error("keyId must be 4-32 lowercase letters/digits");
  const secret = randomBytes(32).toString("base64url");
  return { token: `cyk_${keyId}_${secret}`, sha256: sha256Hex(secret) };
}

// ------------------------------------------------------------------------------------------------ replay cache
/** Remembers ids until they expire. Bounded: when full, the oldest entries go first (they expire first anyway). */
export class ReplayCache {
  private m = new Map<string, number>();
  constructor(private readonly max = 50_000) {}
  /** true when `id` was already seen (a replay); otherwise records it until `expiresAtMs`. */
  seen(id: string, expiresAtMs: number, nowMs: number): boolean {
    const t = this.m.get(id);
    if (t !== undefined && t > nowMs) return true;
    if (this.m.size >= this.max) {
      for (const [k, exp] of this.m) { if (exp <= nowMs || this.m.size >= this.max) this.m.delete(k); else break; }
    }
    this.m.set(id, expiresAtMs);
    return false;
  }
  get size() { return this.m.size; }
}

// ------------------------------------------------------------------------------------------------ subject assertions
export const SUBJECT_AUD = "cyrus-api-v1";
export const SUBJECT_MAX_LIFETIME_S = 120;
export const SUBJECT_SKEW_S = 30;
/** Opaque, stable account id (today the Nxeon user id; later an SSO sub). "@" is refused so an email can never be one. */
export const SUBJECT_RE = /^[A-Za-z0-9_:.-]{4,128}$/;
export type SubjectClaims = { v: 1; iss: string; sub: string; aud: string; iat: number; exp: number; jti: string; kid?: string };
export type SubjectKey = { client: string; kid: string; publicKey: KeyObject };

export function mintSubjectAssertion(claims: SubjectClaims, privateKey: KeyObject): string {
  const p = b64u(JSON.stringify(claims));
  return `${p}.${b64u(edSign(null, Buffer.from(p), privateKey))}`;
}

export type SubjectCheck = { ok: true; claims: SubjectClaims } | { ok: false; code: "bad_subject"; message: string };
export function verifySubjectAssertion(raw: string | null | undefined, o: { client: string; keys: readonly SubjectKey[]; nowMs: number; replay: ReplayCache }): SubjectCheck {
  const bad = (message: string): SubjectCheck => ({ ok: false, code: "bad_subject", message });
  const s = String(raw ?? "").trim();
  if (!s || s.length > 2048) return bad("subject assertion missing or too long");
  const [p, sig, extra] = s.split(".");
  if (!p || !sig || extra !== undefined) return bad("subject assertion is not payload.signature");
  let c: Record<string, unknown>;
  try { c = JSON.parse(Buffer.from(p, "base64url").toString("utf8")); } catch { return bad("subject payload is not JSON"); }
  if (!c || typeof c !== "object" || Array.isArray(c)) return bad("subject payload is not an object");
  if ("email" in c) return bad("subject assertions carry a stable subject id, never an email");
  if (c.iss !== o.client) return bad("subject issuer is not the calling client");
  const keys = o.keys.filter((k) => k.client === o.client && (c.kid === undefined || k.kid === c.kid));
  const sigBuf = Buffer.from(sig, "base64url");
  if (!keys.some((k) => { try { return edVerify(null, Buffer.from(p), k.publicKey, sigBuf); } catch { return false; } })) return bad("subject signature does not verify");
  if (c.v !== 1) return bad("unsupported subject version");
  if (c.aud !== SUBJECT_AUD) return bad("wrong audience");
  if (typeof c.sub !== "string" || !SUBJECT_RE.test(c.sub)) return bad("subject id is not a stable opaque id");
  if (typeof c.jti !== "string" || !/^[A-Za-z0-9_-]{8,64}$/.test(c.jti)) return bad("subject jti missing");
  const iat = Number(c.iat), exp = Number(c.exp), now = Math.floor(o.nowMs / 1000);
  if (!Number.isInteger(iat) || !Number.isInteger(exp) || exp <= iat) return bad("subject times are invalid");
  if (exp - iat > SUBJECT_MAX_LIFETIME_S) return bad(`subject lifetime exceeds ${SUBJECT_MAX_LIFETIME_S} s`);
  if (iat > now + SUBJECT_SKEW_S) return bad("subject issued in the future");
  if (exp + SUBJECT_SKEW_S < now) return bad("subject expired");
  if (o.replay.seen(`sub:${o.client}:${c.jti}`, (exp + SUBJECT_SKEW_S) * 1000, o.nowMs)) return bad("subject assertion already used");
  return { ok: true, claims: c as unknown as SubjectClaims };
}

// ------------------------------------------------------------------------------------------------ request signing (HMAC)
export const SIG_HEADERS = { keyId: "cyrus-key-id", ts: "cyrus-timestamp", nonce: "cyrus-nonce", sig: "cyrus-signature" } as const;
export const REQUEST_SKEW_S = 300;
export const canonicalRequest = (method: string, pathWithQuery: string, ts: string, nonce: string, body: string | Buffer) =>
  [method.toUpperCase(), pathWithQuery, ts, nonce, sha256Hex(body)].join("\n");

export function signRequest(a: { keyId: string; secret: string; method: string; pathWithQuery: string; body: string | Buffer; nowMs: number; nonce?: string }): Record<string, string> {
  const ts = String(Math.floor(a.nowMs / 1000));
  const nonce = a.nonce ?? randomBytes(12).toString("base64url");
  const sig = createHmac("sha256", a.secret).update(canonicalRequest(a.method, a.pathWithQuery, ts, nonce, a.body)).digest("hex");
  return { [SIG_HEADERS.keyId]: a.keyId, [SIG_HEADERS.ts]: ts, [SIG_HEADERS.nonce]: nonce, [SIG_HEADERS.sig]: `v1=${sig}` };
}

export type RequestCheck = { ok: true; keyId: string } | { ok: false; code: "unsigned" | "unknown_key" | "stale" | "replay" | "bad_signature" };
export function verifyRequest(a: { header: (name: string) => string | null; method: string; pathWithQuery: string; body: string | Buffer; secretFor: (keyId: string) => string | null; nowMs: number; replay: ReplayCache }): RequestCheck {
  const keyId = a.header(SIG_HEADERS.keyId), ts = a.header(SIG_HEADERS.ts), nonce = a.header(SIG_HEADERS.nonce), sig = a.header(SIG_HEADERS.sig);
  if (!keyId || !ts || !nonce || !sig || !/^\d{9,11}$/.test(ts) || !/^[A-Za-z0-9_-]{8,64}$/.test(nonce)) return { ok: false, code: "unsigned" };
  const secret = a.secretFor(keyId);
  if (!secret) return { ok: false, code: "unknown_key" };
  if (Math.abs(Math.floor(a.nowMs / 1000) - Number(ts)) > REQUEST_SKEW_S) return { ok: false, code: "stale" };
  const want = `v1=${createHmac("sha256", secret).update(canonicalRequest(a.method, a.pathWithQuery, ts, nonce, a.body)).digest("hex")}`;
  if (!safeEqual(sig, want)) return { ok: false, code: "bad_signature" };
  if (a.replay.seen(`req:${keyId}:${nonce}`, (Number(ts) + REQUEST_SKEW_S) * 1000, a.nowMs)) return { ok: false, code: "replay" };
  return { ok: true, keyId };
}

// ------------------------------------------------------------------------------------------------ webhooks
export const WEBHOOK_TOLERANCE_S = 300;
export const signWebhook = (secret: string, id: string, timestamp: string, body: string) => `v1=${createHmac("sha256", secret).update(`${id}.${timestamp}.${body}`).digest("hex")}`;

/** Receiver side (what Nxeon runs): signature, freshness, then exactly-once by id. */
export function verifyWebhook(a: { secret: string; id: string | null; timestamp: string | null; body: string; signature: string | null; nowMs: number; replay: ReplayCache }): { ok: true } | { ok: false; code: "unsigned" | "stale" | "bad_signature" | "duplicate" } {
  if (!a.id || !a.timestamp || !a.signature || !/^\d{9,11}$/.test(a.timestamp)) return { ok: false, code: "unsigned" };
  if (Math.abs(Math.floor(a.nowMs / 1000) - Number(a.timestamp)) > WEBHOOK_TOLERANCE_S) return { ok: false, code: "stale" };
  // several "v1=" values may be sent during a secret rotation
  const want = signWebhook(a.secret, a.id, a.timestamp, a.body);
  if (!a.signature.split(/[ ,]+/).some((s) => safeEqual(s, want))) return { ok: false, code: "bad_signature" };
  if (a.replay.seen(`wh:${a.id}`, a.nowMs + 24 * 3600_000, a.nowMs)) return { ok: false, code: "duplicate" };
  return { ok: true };
}
// Cyrus API v1 configuration, from the environment (Cyrus-owned names). SERVER ONLY. Fails CLOSED: off unless
// CYRUS_API_V1 is on; a malformed key list makes every request 503 (never "no auth").
//   CYRUS_API_V1=1                     the flag (default off: every /api/cyrus/v1 route answers 404)
//   CYRUS_API_V1_KEYS=[{"id":"nxeon01","client":"nxeon","sha256":"<hex of the secret>","scopes":["projects:read"],"rpm":120}]
//   CYRUS_API_V1_SUBJECT_KEYS=[{"client":"nxeon","kid":"s1","publicKey":"<base64 DER SPKI Ed25519>"}]
//   CYRUS_API_V1_CATALOG_FILE=/path/entries.jsonl   (optional; CatalogEntry v1 per line; until the catalog has a DB index)
import { createPublicKey } from "node:crypto";
import { isTrue } from "../../host/types";
import { isScope, type Scope } from "./scopes";
import type { SubjectKey } from "./signing";

export type ApiKey = { id: string; client: string; sha256: string; scopes: Scope[]; rpm: number };
export type ApiV1Config = {
  enabled: boolean;
  /** set when the config cannot be trusted: every request answers 503 */
  error: string | null;
  keys: ApiKey[];
  subjectKeys: SubjectKey[];
  catalogFile: string | null;
};

export const DEFAULT_RPM = 120;
const CLIENT_RE = /^[a-z][a-z0-9-]{1,31}$/;

function parseList(raw: string | undefined, name: string): unknown[] {
  if (!raw || !raw.trim()) return [];
  const v = JSON.parse(raw);
  if (!Array.isArray(v)) throw new Error(`${name} must be a JSON array`);
  return v;
}

let cache: { raw: string; cfg: ApiV1Config } | null = null;

export function apiV1Config(env: Record<string, string | undefined> = process.env): ApiV1Config {
  const raw = [env.CYRUS_API_V1, env.CYRUS_API_V1_KEYS, env.CYRUS_API_V1_SUBJECT_KEYS, env.CYRUS_API_V1_CATALOG_FILE].join("\u0000");
  if (cache && cache.raw === raw) return cache.cfg;
  const cfg: ApiV1Config = { enabled: isTrue(env.CYRUS_API_V1), error: null, keys: [], subjectKeys: [], catalogFile: env.CYRUS_API_V1_CATALOG_FILE?.trim() || null };
  try {
    const ids = new Set<string>();
    for (const k of parseList(env.CYRUS_API_V1_KEYS, "CYRUS_API_V1_KEYS")) {
      const o = (k ?? {}) as Record<string, unknown>;
      if (typeof o.id !== "string" || !/^[a-z0-9]{4,32}$/.test(o.id)) throw new Error("a key id must be 4-32 lowercase letters/digits");
      if (ids.has(o.id)) throw new Error(`duplicate key id ${o.id}`);
      if (typeof o.client !== "string" || !CLIENT_RE.test(o.client)) throw new Error(`key ${o.id}: bad client`);
      if (typeof o.sha256 !== "string" || !/^[0-9a-f]{64}$/.test(o.sha256)) throw new Error(`key ${o.id}: sha256 must be 64 hex`);
      const rpm = o.rpm === undefined ? DEFAULT_RPM : Number(o.rpm);
      if (!Number.isInteger(rpm) || rpm < 1 || rpm > 10_000) throw new Error(`key ${o.id}: rpm must be 1-10000`);
      ids.add(o.id);
      cfg.keys.push({ id: o.id, client: o.client, sha256: o.sha256, scopes: (Array.isArray(o.scopes) ? o.scopes : []).filter(isScope), rpm });
    }
    for (const k of parseList(env.CYRUS_API_V1_SUBJECT_KEYS, "CYRUS_API_V1_SUBJECT_KEYS")) {
      const o = (k ?? {}) as Record<string, unknown>;
      if (typeof o.client !== "string" || !CLIENT_RE.test(o.client)) throw new Error("subject key: bad client");
      if (typeof o.kid !== "string" || !/^[A-Za-z0-9_-]{1,32}$/.test(o.kid)) throw new Error("subject key: bad kid");
      if (typeof o.publicKey !== "string") throw new Error(`subject key ${o.kid}: publicKey missing`);
      const publicKey = createPublicKey({ key: Buffer.from(o.publicKey, "base64"), format: "der", type: "spki" });
      if (publicKey.asymmetricKeyType !== "ed25519") throw new Error(`subject key ${o.kid}: must be Ed25519`);
      cfg.subjectKeys.push({ client: o.client, kid: o.kid, publicKey });
    }
  } catch (e) {
    cfg.error = (e as Error).message || "bad CYRUS_API_V1 config";
    cfg.keys = []; cfg.subjectKeys = [];
  }
  cache = { raw, cfg };
  return cfg;
}
// Cyrus API v1 scopes. A service token carries a subset; an operation needs all of its scopes. Unknown scope names in
// a key's config are ignored (never widen). Pure.
export const SCOPES = [
  "projects:read", "projects:write", "builds:read", "builds:write", "installs:read", "installs:write",
  "catalog:read", "mods:read", "account:read", "webhooks:manage", "admin:read",
] as const;
export type Scope = (typeof SCOPES)[number];
export const isScope = (s: unknown): s is Scope => typeof s === "string" && (SCOPES as readonly string[]).includes(s);
// Real wiring of the Cyrus API v1 handlers (./http.ts). SERVER ONLY. HOST SEAM: Cyrus' own tables through cyrusDb, the
// rate limiter through the host, the plan through tokens tierOf (the same lookup the studios use), nothing from Nxeon.
import { readFileSync, statSync } from "node:fs";
import { cyrusDb } from "../../db";
import { getHost } from "../../host";
import { tierOf } from "../../tokens/access";
import { validateCatalogEntry } from "../../library/v2/entry";
import { createMemoryCatalogIndex, type CatalogIndex } from "../../library/v2/retrieval";
import { apiV1Config } from "./config";
import { ReplayCache } from "./signing";
import type { V1Deps } from "./http";

const replay = new ReplayCache();

/** Max bytes of CYRUS_API_V1_CATALOG_FILE read into memory (a stopgap until the catalog has a database index). */
export const CATALOG_FILE_MAX_BYTES = 64 * 1024 * 1024;
let catalogCache: { key: string; index: CatalogIndex } | null = null;

/** A memory index over a CatalogEntry JSONL file; invalid lines are skipped, a too-large or missing file = no catalog. */
export async function fileCatalog(file: string | null): Promise<CatalogIndex | null> {
  if (!file) return null;
  let st;
  try { st = statSync(file); } catch { return null; }
  if (!st.isFile() || st.size > CATALOG_FILE_MAX_BYTES) return null;
  const key = `${file}:${st.size}:${st.mtimeMs}`;
  if (catalogCache?.key === key) return catalogCache.index;
  const entries = [];
  for (const line of readFileSync(file, "utf8").split("\n")) {
    if (!line.trim()) continue;
    try { const v = validateCatalogEntry(JSON.parse(line)); if (v.ok) entries.push(v.entry); } catch { /* skip */ }
  }
  const index = createMemoryCatalogIndex(entries);
  catalogCache = { key, index };
  return index;
}

const PROJECT_SELECT = { id: true, userId: true, game: true, namespace: true, title: true, rootBuildId: true, headRevisionId: true, lastPassingRevisionId: true, revisionCount: true, createdAt: true, updatedAt: true } as const;

export function v1Deps(env: Record<string, string | undefined> = process.env): V1Deps {
  return {
    config: () => apiV1Config(env),
    now: () => new Date(),
    replay,
    rateLimit: (key, max, windowMs) => getHost().rateLimit.check(key, { max, windowMs }),
    store: {
      listProjects: (userId, limit, after) => cyrusDb.cyrusProject.findMany({
        where: { userId, ...(after ? { OR: [{ createdAt: { lt: after.createdAt } }, { createdAt: after.createdAt, id: { lt: after.id } }] } : {}) },
        orderBy: [{ createdAt: "desc" }, { id: "desc" }], take: limit, select: PROJECT_SELECT,
      }),
      getProject: (id) => cyrusDb.cyrusProject.findUnique({ where: { id }, select: PROJECT_SELECT }),
      revisions: (ids) => cyrusDb.cyrusRevision.findMany({ where: { id: { in: ids } }, select: { id: true, projectId: true, seq: true, kind: true, status: true, message: true, modBuildId: true, manifest: true, spec: true, createdAt: true } }),
      getBuild: (id) => cyrusDb.modBuild.findUnique({
        where: { id },
        select: { id: true, userId: true, status: true, prompt: true, changeRequest: true, baseBuildId: true, rootBuildId: true, mcVersion: true, pluginName: true, version: true, result: true, error: true, errorCode: true, attempts: true, durationMs: true, jarName: true, jarSize: true, jarSha256: true, cyrus: true, createdAt: true, updatedAt: true, finishedAt: true },
      }),
    },
    catalog: () => fileCatalog(apiV1Config(env).catalogFile),
    planOf: (userId) => tierOf(userId),
    // same fail-closed licence rule as the sound library (lib/cyrus/sound/host.ts soundLibraryCleared)
    proprietaryCleared: () => env.CYRUS_SOUND_LIBRARY_CLEARED === "1",
    log: (m) => console.error(m),
  };
}

// Cyrus API v1: the framework-free handlers (Request -> Response) of the LIVE operations in ./openapi.ts. Read-only.
// app/api/cyrus/v1/** are one-line wrappers with v1Deps() (./deps.ts); tests pass fakes. Every request:
//   flag (off = 404, as if the route did not exist) -> config sane (else 503) -> service token (401) -> scopes (403)
//   -> rate limit per key (429) -> subject assertion when the operation is per-user (400/401) -> handler.
// Objects that are not the subject's answer 404, exactly like unknown ones. Errors: {error:{code,message,issues?,requestId}}.
// HOST SEAM: no Nxeon imports (data comes through V1Deps).
import { randomBytes } from "node:crypto";
import { access as catalogAccess } from "../../library/v2/tools";
import { CATALOG_KINDS, catalogRef, type CatalogEntry, type CatalogKind } from "../../library/v2/entry";
import type { CatalogIndex } from "../../library/v2/retrieval";
import { API_VERSION, type ApiIssue } from "./schemas";
import { BUILD_ID_PATTERN, ENTRY_ID_PATTERN, OPERATIONS, PROJECT_ID_PATTERN, type Operation } from "./openapi";
import type { ApiKey, ApiV1Config } from "./config";
import { parseServiceToken, safeEqual, sha256Hex, verifySubjectAssertion, type ReplayCache } from "./signing";

export type LiveOperationId = "getHealth" | "listProjects" | "getProject" | "getBuild" | "searchCatalog" | "getCatalogEntry";

export type ProjectRow = { id: string; userId: string; game: string; namespace: string; title: string | null; rootBuildId: string | null; headRevisionId: string | null; lastPassingRevisionId: string | null; revisionCount: number; createdAt: Date; updatedAt: Date };
export type RevisionRow = { id: string; projectId: string; seq: number; kind: string; status: string; message: string | null; modBuildId: string | null; manifest: unknown; spec: unknown; createdAt: Date };
export type BuildRow = {
  id: string; userId: string; status: string; prompt: string; changeRequest: string | null; baseBuildId: string | null; rootBuildId: string | null;
  mcVersion: string; pluginName: string | null; version: string | null; result: unknown; error: string | null; errorCode: string | null; attempts: number;
  durationMs: number | null; jarName: string | null; jarSize: number | null; jarSha256: string | null; cyrus: unknown; createdAt: Date; updatedAt: Date; finishedAt: Date | null;
};

export type V1Deps = {
  config: () => ApiV1Config;
  now: () => Date;
  replay: ReplayCache;
  rateLimit: (key: string, max: number, windowMs: number) => { ok: boolean; retryAfterSec: number; remaining: number };
  store: {
    /** newest first; `after` = the last row of the previous page */
    listProjects(userId: string, limit: number, after: { createdAt: Date; id: string } | null): Promise<ProjectRow[]>;
    getProject(id: string): Promise<ProjectRow | null>;
    revisions(ids: string[]): Promise<RevisionRow[]>;
    getBuild(id: string): Promise<BuildRow | null>;
  };
  /** null = no catalog backend configured (503 catalog_unavailable) */
  catalog: () => Promise<CatalogIndex | null>;
  /** the subject's raw plan (asset-gate understands it); a throw = unknown = fail closed */
  planOf: (userId: string) => Promise<unknown>;
  proprietaryCleared: () => boolean;
  requestId?: () => string;
  log?: (msg: string) => void;
};

type Ctx = { requestId: string; headers: Record<string, string> };
const send = (ctx: Ctx, status: number, body: unknown, extra: Record<string, string> = {}) =>
  Response.json(body, { status, headers: { "cache-control": "no-store", "x-robots-tag": "noindex", "cyrus-api-version": API_VERSION, "cyrus-request-id": ctx.requestId, ...ctx.headers, ...extra } });
const fail = (ctx: Ctx, status: number, code: string, message: string, issues?: ApiIssue[], extra?: Record<string, string>) =>
  send(ctx, status, { error: { code, message, ...(issues?.length ? { issues } : {}), requestId: ctx.requestId } }, extra);
const iso = (d: Date | null) => (d ? d.toISOString() : null);

class BadInput extends Error { constructor(public issues: ApiIssue[]) { super("bad input"); } }
const issue = (path: string, message: string, code = "invalid"): ApiIssue => ({ path, code, message });

function intParam(u: URL, name: string, min: number, max: number, dflt: number): number {
  const raw = u.searchParams.get(name);
  if (raw === null || raw === "") return dflt;
  if (!/^\d{1,6}$/.test(raw) || Number(raw) < min || Number(raw) > max) throw new BadInput([issue(name, `${name} must be a whole number ${min}-${max}`)]);
  return Number(raw);
}
const encCursor = (o: Record<string, unknown>) => Buffer.from(JSON.stringify(o)).toString("base64url");
function decCursor<T>(raw: string | null, check: (o: Record<string, unknown>) => T | null): T | null {
  if (!raw) return null;
  try {
    if (raw.length > 200) throw new Error();
    const o = JSON.parse(Buffer.from(raw, "base64url").toString("utf8"));
    const v = o && typeof o === "object" ? check(o) : null;
    if (v) return v;
  } catch { /* falls through */ }
  throw new BadInput([issue("cursor", "cursor is not one this API returned")]);
}

// ------------------------------------------------------------------------------------------------ auth
type Caller = { key: ApiKey; subject: string | null };
type AuthOut = { ok: true; caller: Caller } | { ok: false; res: Response };

function authenticate(req: Request, op: Operation, cfg: ApiV1Config, deps: V1Deps, ctx: Ctx): AuthOut {
  const no = (res: Response): AuthOut => ({ ok: false, res });
  const h = req.headers.get("authorization") ?? "";
  const tok = parseServiceToken(h.startsWith("Bearer ") ? h.slice(7) : "");
  // unknown key and wrong secret look the same to the caller
  const key = tok ? cfg.keys.find((k) => k.id === tok.keyId) ?? null : null;
  if (!tok || !key || !safeEqual(sha256Hex(tok.secret), key.sha256)) return no(fail(ctx, 401, "unauthorized", "a valid Cyrus service token is required", undefined, { "www-authenticate": 'Bearer realm="cyrus-api-v1"' }));
  const missing = op.scopes.filter((s) => !key.scopes.includes(s));
  if (missing.length) return no(fail(ctx, 403, "forbidden_scope", `this token lacks ${missing.join(", ")}`));
  const rl = deps.rateLimit(`cyrus-api-v1:${key.id}`, key.rpm, 60_000);
  ctx.headers["ratelimit-limit"] = String(key.rpm);
  ctx.headers["ratelimit-remaining"] = String(Math.max(0, rl.remaining));
  if (!rl.ok) return no(fail(ctx, 429, "rate_limited", "too many requests for this token", undefined, { "retry-after": String(Math.max(1, rl.retryAfterSec)) }));
  if (!op.subject) return { ok: true, caller: { key, subject: null } };
  const raw = req.headers.get("cyrus-subject");
  if (!raw) return no(fail(ctx, 400, "subject_required", "this operation acts for one account: send the Cyrus-Subject assertion"));
  const v = verifySubjectAssertion(raw, { client: key.client, keys: cfg.subjectKeys, nowMs: deps.now().getTime(), replay: deps.replay });
  if (!v.ok) return no(fail(ctx, 401, v.code, v.message));
  return { ok: true, caller: { key, subject: v.claims.sub } };
}

