// ------------------------------------------------------------------------------------------------ operations
const re = (p: string) => new RegExp(p);
const PROJECT_RE = re(PROJECT_ID_PATTERN), BUILD_RE = re(BUILD_ID_PATTERN), ENTRY_RE = re(ENTRY_ID_PATTERN);
type Handler = (a: { req: Request; url: URL; params: Record<string, string>; caller: Caller; deps: V1Deps; ctx: Ctx }) => Promise<Response>;

const notFound = (ctx: Ctx) => fail(ctx, 404, "not_found", "not found");

async function gateFor(subject: string, deps: V1Deps) {
  let plan: unknown = null;
  try { plan = await deps.planOf(subject); } catch { plan = null; } // unknown plan = fail closed
  return catalogAccess(plan, deps.proprietaryCleared());
}

const HANDLERS: Record<LiveOperationId, Handler> = {
  async getHealth({ caller, deps, ctx }) {
    return send(ctx, 200, { ok: true, api: "cyrus", version: API_VERSION, time: deps.now().toISOString(), client: caller.key.client, scopes: caller.key.scopes });
  },

  async listProjects({ url, caller, deps, ctx }) {
    const limit = intParam(url, "limit", 1, 100, 20);
    const after = decCursor(url.searchParams.get("cursor"), (o) => (typeof o.t === "string" && typeof o.id === "string" && !Number.isNaN(Date.parse(o.t)) ? { createdAt: new Date(o.t), id: o.id } : null));
    const rows = await deps.store.listProjects(caller.subject!, limit + 1, after);
    const page = rows.slice(0, limit);
    const last = page[page.length - 1];
    return send(ctx, 200, { data: page.map(projectView), nextCursor: rows.length > limit && last ? encCursor({ t: last.createdAt.toISOString(), id: last.id }) : null });
  },

  async getProject({ params, caller, deps, ctx }) {
    const id = params.projectId ?? "";
    if (!PROJECT_RE.test(id)) return notFound(ctx);
    const p = await deps.store.getProject(id);
    if (!p || p.userId !== caller.subject) return notFound(ctx);
    const ids = [p.headRevisionId, p.lastPassingRevisionId].filter((x): x is string => !!x);
    const revs = ids.length ? await deps.store.revisions([...new Set(ids)]) : [];
    const own = (rid: string | null) => revs.find((r) => r.id === rid && r.projectId === p.id) ?? null;
    const head = own(p.headRevisionId), lastPassing = own(p.lastPassingRevisionId);
    return send(ctx, 200, { ...projectView(p), head: head ? revisionView(head) : null, lastPassing: lastPassing ? revisionView(lastPassing) : null, spec: head?.spec ?? null });
  },

  async getBuild({ params, caller, deps, ctx }) {
    const id = params.buildId ?? "";
    if (!BUILD_RE.test(id)) return notFound(ctx);
    const b = await deps.store.getBuild(id);
    if (!b || b.userId !== caller.subject) return notFound(ctx);
    return send(ctx, 200, buildView(b));
  },

  async searchCatalog({ url, caller, deps, ctx }) {
    const q = (url.searchParams.get("q") ?? "").trim();
    const issues: ApiIssue[] = [];
    if (q.length < 2 || q.length > 120) issues.push(issue("q", "q must be 2-120 characters"));
    const kindRaw = url.searchParams.get("kind");
    if (kindRaw !== null && !(CATALOG_KINDS as readonly string[]).includes(kindRaw)) issues.push(issue("kind", `kind must be one of ${CATALOG_KINDS.join(", ")}`));
    const gameRaw = url.searchParams.get("game");
    if (gameRaw !== null && !/^[a-z][a-z0-9-]{1,31}$/.test(gameRaw)) issues.push(issue("game", "game must be a game id"));
    if (issues.length) throw new BadInput(issues);
    const minQuality = intParam(url, "minQuality", 0, 100, 40);
    const limit = intParam(url, "limit", 1, 20, 10);
    const offset = decCursor(url.searchParams.get("cursor"), (o) => (Number.isInteger(o.o) && (o.o as number) >= 0 && (o.o as number) <= 10_000 ? (o.o as number) : null)) ?? 0;
    const index = await deps.catalog();
    if (!index) return fail(ctx, 503, "catalog_unavailable", "the asset catalog is not available on this deployment");
    const a = await gateFor(caller.subject!, deps);
    if (!a.plan) return fail(ctx, 403, "plan_unknown", "the account's plan could not be read; assets cannot be picked right now");
    let kinds: CatalogKind[] = a.kinds;
    if (kindRaw !== null) kinds = kinds.includes(kindRaw as CatalogKind) ? [kindRaw as CatalogKind] : [];
    if (!kinds.length || !a.tiers.length) return fail(ctx, 403, "asset_locked", "this plan cannot use library assets of that kind");
    const r = await index.search({ text: q, kinds, game: gameRaw, minQuality, tiers: a.tiers, limit, offset, statuses: ["published"] });
    const data = r.hits.map((h) => ({
      id: h.entry.id, ref: catalogRef(h.entry.id), kind: h.entry.kind, title: h.entry.title, shortDescription: h.entry.shortDescription,
      tags: h.entry.tags.slice(0, 8), quality: h.entry.quality.score, fit: gameRaw ? h.entry.games[gameRaw]?.fit ?? "unknown" : "unknown", variants: Math.max(1, h.groupSize),
    }));
    const next = offset + r.hits.length;
    return send(ctx, 200, { data, total: r.total, game: gameRaw, nextCursor: r.hits.length === limit && next < r.total ? encCursor({ o: next }) : null });
  },

  async getCatalogEntry({ params, caller, deps, ctx }) {
    const raw = params.entryId ?? "";
    if (!ENTRY_RE.test(raw)) return notFound(ctx);
    const index = await deps.catalog();
    if (!index) return fail(ctx, 503, "catalog_unavailable", "the asset catalog is not available on this deployment");
    const e = await index.get(raw.replace(/^cat:/, ""));
    const a = await gateFor(caller.subject!, deps);
    // an entry the subject may not use is reported as not found (no metadata leak across gates), same as catalog_get
    if (!e || e.status !== "published" || !a.kinds.includes(e.kind) || !a.tiers.includes(e.licence.tier)) return notFound(ctx);
    return send(ctx, 200, catalogEntryView(e));
  },
};

export const LIVE_OPERATIONS = Object.keys(HANDLERS) as LiveOperationId[];

/** The single entry point every app/api/cyrus/v1 route calls. Never throws. */
export async function handleV1(opId: LiveOperationId, req: Request, params: Record<string, string>, deps: V1Deps): Promise<Response> {
  const ctx: Ctx = { requestId: deps.requestId?.() ?? randomBytes(9).toString("base64url"), headers: {} };
  let cfg: ApiV1Config;
  try { cfg = deps.config(); } catch { return fail(ctx, 503, "api_misconfigured", "the Cyrus API is not configured correctly"); }
  if (!cfg.enabled) return fail(ctx, 404, "not_found", "not found");
  if (cfg.error) { deps.log?.(`[cyrus-api-v1] config refused: ${cfg.error}`); return fail(ctx, 503, "api_misconfigured", "the Cyrus API is not configured correctly"); }
  const op = OPERATIONS.find((o) => o.id === opId && o.status === "live");
  if (!op || op.method.toUpperCase() !== req.method.toUpperCase()) return fail(ctx, 404, "not_found", "not found");
  const auth = authenticate(req, op, cfg, deps, ctx);
  if (!auth.ok) return auth.res;
  try {
    return await HANDLERS[opId]({ req, url: new URL(req.url), params, caller: auth.caller, deps, ctx });
  } catch (e) {
    if (e instanceof BadInput) return fail(ctx, 400, "bad_request", "the request is invalid", e.issues);
    deps.log?.(`[cyrus-api-v1] ${opId} ${ctx.requestId} failed: ${(e as Error).message}`);
    return fail(ctx, 500, "internal", "something went wrong; quote the requestId");
  }
}

