};

export type RouteWorld = { games: RouteGame[]; projects: RouteProject[] };

/* ───────────── Text helpers ───────────── */

export function normalizeText(s: string): string {
  return s
    .toLowerCase()
    .replace(/[‘’‛`]/g, "'")
    .replace(/[“”"]/g, " ")
    .replace(/'s\b/g, "")
    .replace(/[^a-z0-9'\s/-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

const tokens = (s: string) => normalizeText(s).split(/[\s/-]+/).filter(Boolean);

