export type GateInput = {
  /** result.capabilities straight from the build row (may be invalid or absent). */
  capabilities: unknown;
  /** The `cyrus_mod_networking_enabled` setting. */
  networkingEnabled: boolean;
  /** What the customer confirmed in CapabilityConsent: the manifest sha256 they saw. */
  acceptedSha256?: string | null;
};
export type GateResult = { ok: true; manifest: CyrusCapabilities | null } | { ok: false; status: 403 | 409 | 422; code: string; error: string };

/**
 * Install gate. A mod without a manifest installs as before. A mod with one needs the
 * platform switch on, a manifest that passes today's policy, and an explicit consent for
 * exactly that manifest (hash), so a changed manifest asks again.
 */
export function capabilityGate({ capabilities, networkingEnabled, acceptedSha256 }: GateInput): GateResult {
  if (capabilities == null) return { ok: true, manifest: null };
  if (!networkingEnabled) return { ok: false, status: 403, code: "networking_off", error: "Mods that connect to the internet are switched off on Nxeon right now." };
  const v = validateCapabilities(capabilities);
  if (!v.ok) return { ok: false, status: 422, code: "manifest_invalid", error: "This mod's network permissions no longer meet Nxeon's rules. Rebuild it to install." };
  if (!acceptedSha256 || acceptedSha256 !== v.manifest.sha256) return { ok: false, status: 409, code: "consent_required", error: "Review what this mod connects to and confirm before installing." };
  return { ok: true, manifest: v.manifest };
}

// ------------------------------------------------------------ free network limits ----
/** Ordinary networking limits per installed mod (no token cost; they stop nuisance traffic). */
export const NET_LIMITS = POLICY.limits as {
  callsPerMinute: number; burst: number; dailyBytesOut: number; dailyBytesIn: number; maxRequestKiB: number;
  connectTimeoutMs: number; callTimeoutMs: number; maxRedirects: number; workerThreads: number; queue: number;
};

export type NetUsage = { callsLastMinute: number; bytesOutToday: number; bytesInToday: number };
export type NetDecision = { ok: true } | { ok: false; code: "rate_limited" | "daily_bytes_out" | "daily_bytes_in" | "request_too_large"; message: string };

/** The wrapper's pre-call check, as a pure function (the Java wrapper mirrors it). */
export function checkNetLimits(u: NetUsage, requestBytes: number, limits = NET_LIMITS): NetDecision {
  if (requestBytes > limits.maxRequestKiB * 1024) return { ok: false, code: "request_too_large", message: `Requests are limited to ${limits.maxRequestKiB} KiB.` };
  if (u.callsLastMinute >= limits.callsPerMinute) return { ok: false, code: "rate_limited", message: `A mod may make ${limits.callsPerMinute} web calls a minute.` };
  if (u.bytesOutToday + requestBytes > limits.dailyBytesOut) return { ok: false, code: "daily_bytes_out", message: "This mod has sent its daily data allowance." };
  if (u.bytesInToday >= limits.dailyBytesIn) return { ok: false, code: "daily_bytes_in", message: "This mod has received its daily data allowance." };
  return { ok: true };
}
}

